'use client';

import { useId, useRef } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  SearchIcon,
} from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { Input } from '@/registry/ndeko/ui/input';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { POPULAR_SEARCHES, SITE, TYPES } from './data';
import { optionIdOf, ResultList } from './results';
import {
  correctionOf,
  countOfType,
  matchesOf,
  wordsOf,
  type TypeFilter,
} from './search';
import {
  INITIAL,
  LOOP_AFTER_MS,
  pageCountOf,
  pageOfResults,
  reducer,
  RESTING,
  resultsIn,
  SCRIPT,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const FILTERS: { id: TypeFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  ...TYPES,
];

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

const KEY_MOTION = 'transition-[scale] duration-150';

function filterOf(values: unknown[]) {
  const [value] = values;
  const filter = FILTERS.find((candidate) => candidate.id === value);
  return filter?.id;
}

function resultsWordOf(count: number) {
  if (count === 1) {
    return 'result';
  }
  return 'results';
}

/** Below a millisecond the clock of the browser is too coarse to say more. */
function timingOf(searchMs: number) {
  if (searchMs < 1) {
    return 'in under 1 ms';
  }
  return `in ${Math.round(searchMs)} ms`;
}

function spokenOf(count: number, hasWords: boolean) {
  if (!hasWords) {
    return '';
  }
  if (count === 0) {
    return 'No results';
  }
  return `${count} ${resultsWordOf(count)}`;
}

function pagesOf(pageCount: number) {
  return Array.from({ length: pageCount }, (_, index) => index + 1);
}

function currentPageOf(isCurrent: boolean): 'page' | undefined {
  if (isCurrent) {
    return 'page';
  }
  return undefined;
}

function activeIdOf(listId: string, activeIndex: number, hasResults: boolean) {
  const hasActive = activeIndex >= 0;
  if (!hasResults || !hasActive) {
    return undefined;
  }
  return optionIdOf(listId, activeIndex);
}

const TYPE_NOUN: Record<TypeFilter, string> = {
  all: 'page',
  guide: 'guide',
  api: 'API reference page',
  changelog: 'changelog entry',
  community: 'community thread',
};

function hiddenLineOf(type: TypeFilter, query: string) {
  const noun = TYPE_NOUN[type];
  const trimmed = query.trim();
  return `No ${noun} matches “${trimmed}”`;
}

type PopularSearchesProps = {
  onPick: (query: string, control: HTMLElement) => void;
  className?: string;
};

function PopularSearches({ onPick, className }: PopularSearchesProps) {
  return (
    <ul className={cn('flex flex-wrap gap-2', className)}>
      {POPULAR_SEARCHES.map((query) => (
        <li key={query}>
          <Button
            type='button'
            variant='outline'
            size='sm'
            onClick={(event) => onPick(query, event.currentTarget)}
          >
            {query}
          </Button>
        </li>
      ))}
    </ul>
  );
}

export default function Search01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const listId = useId();
  const words = wordsOf(state.query);
  const hasWords = words.length > 0;
  const matches = matchesOf(state.query);
  const results = resultsIn(state);
  const shownResults = pageOfResults(state);
  const resultCount = results.length;
  const pageCount = pageCountOf(resultCount);
  const hasResults = resultCount > 0;
  const hasMatches = matches.length > 0;
  const isNothingFound = hasWords && !hasMatches;
  const isHiddenByType = hasMatches && !hasResults;
  let correction: string | null = null;
  if (isNothingFound) {
    correction = correctionOf(state.query);
  }
  const hasPages = pageCount > 1;
  const pages = pagesOf(pageCount);
  const activeId = activeIdOf(listId, state.activeIndex, hasResults);
  const resultLine = spokenOf(resultCount, hasWords);
  const message = spokenUnless(isAutoplaying, resultLine);
  const canReplay = isFinished && !isAutoplaying;
  useKeptHeight(ref);

  function search(value: string) {
    act({ type: 'typed', value });
  }

  /** A pick replaces the part of the page that held the focus: a keyboard goes back to the field. */
  function returnKeyboardToField(control: HTMLElement) {
    const isFromKeyboard = control.matches(':focus-visible');
    if (isFromKeyboard) {
      inputRef.current?.focus();
    }
  }

  function pickSearch(value: string, control: HTMLElement) {
    search(value);
    returnKeyboardToField(control);
  }

  function showEveryType(control: HTMLElement) {
    act({ type: 'typePicked', filter: 'all' });
    returnKeyboardToField(control);
  }

  function pickFilter(values: unknown[]) {
    const filter = filterOf(values);
    if (filter) {
      act({ type: 'typePicked', filter });
    }
  }

  function openActive() {
    let index = state.activeIndex;
    if (index < 0) {
      index = 0;
    }
    const optionId = optionIdOf(listId, index);
    const option = document.getElementById(optionId);
    option?.click();
  }

  function handleKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      act({ type: 'moved', by: 1 });
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      act({ type: 'moved', by: -1 });
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      act({ type: 'cleared' });
      return;
    }
    const isEnter = event.key === 'Enter';
    if (isEnter && hasResults) {
      event.preventDefault();
      openActive();
    }
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-3xl flex-col gap-5 px-4 py-6 @2xl:px-8 @2xl:py-10'>
          <header className='flex min-h-8 items-center gap-2'>
            <a
              href={SITE.homeHref}
              className={cn(
                'flex items-center gap-2 rounded-md text-sm font-semibold',
                FOCUS_RING
              )}
            >
              <CompanyMark seed={SITE.name} size='lg' />
              {SITE.name}
            </a>
            <span className='text-muted-foreground text-sm'>Docs</span>
            <span className='flex-1' />
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </header>

          <div className='flex flex-col gap-3'>
            <div className='relative'>
              <label htmlFor={inputId} className='sr-only'>
                Search the docs
              </label>
              <SearchIcon className='text-muted-foreground pointer-events-none absolute start-4 top-1/2 size-[18px] -translate-y-1/2' />
              <Input
                ref={inputRef}
                id={inputId}
                type='search'
                role='combobox'
                autoComplete='off'
                spellCheck={false}
                aria-autocomplete='list'
                aria-expanded={hasResults}
                aria-controls={listId}
                aria-activedescendant={activeId}
                placeholder='Search guides, endpoints and errors'
                value={state.query}
                onChange={(event) => search(event.target.value)}
                onKeyDown={handleKeys}
                className='h-12 rounded-xl ps-11 pe-4 md:text-sm'
              />
            </div>

            <div className='flex min-h-6 flex-wrap items-center gap-x-4 gap-y-2'>
              {hasWords && (
                <p className='text-muted-foreground flex items-baseline gap-1 text-xs tabular-nums'>
                  <MotionNumber
                    value={resultCount}
                    className='text-foreground font-medium'
                  />
                  {resultsWordOf(resultCount)} {timingOf(state.searchMs)}
                </p>
              )}
              {!hasWords && (
                <p className='text-muted-foreground text-xs'>
                  Search every guide, endpoint and changelog entry
                </p>
              )}
              <p
                aria-hidden='true'
                className='text-muted-foreground ms-auto hidden items-center gap-1 text-xs @md:flex'
              >
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-down')
                  )}
                >
                  ↓
                </Kbd>
                <Kbd>Enter</Kbd>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-escape')
                  )}
                >
                  Esc
                </Kbd>
              </p>
            </div>
          </div>

          <div className='relative -mx-4 overflow-x-auto px-4 @2xl:mx-0 @2xl:px-0'>
            <ToggleGroup
              aria-label='Type of page'
              value={[state.type]}
              onValueChange={pickFilter}
              travel
              indicatorClassName={THUMB}
              className='bg-foreground/[0.04] rounded-xl p-1'
            >
              {FILTERS.map((filter) => (
                <ToggleGroupItem
                  key={filter.id}
                  value={filter.id}
                  className={cn(
                    'h-7 gap-1.5 rounded-lg px-2.5 text-xs',
                    pressedQuietOf(pressed === `type-${filter.id}`)
                  )}
                >
                  {filter.label}
                  <MotionNumber
                    value={countOfType(matches, filter.id)}
                    className='text-muted-foreground'
                  />
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
          </div>

          {hasResults && (
            <ResultList
              listId={listId}
              results={shownResults}
              words={words}
              activeIndex={state.activeIndex}
            />
          )}

          {hasPages && (
            <nav
              aria-label='Pages of results'
              className='flex items-center justify-center gap-1'
            >
              <Button
                type='button'
                variant='ghost'
                size='icon'
                aria-label='Previous page'
                disabled={state.page === 1}
                focusableWhenDisabled
                onClick={() => act({ type: 'paged', page: state.page - 1 })}
              >
                <ChevronLeftIcon />
              </Button>
              {pages.map((page) => {
                const isCurrent = page === state.page;
                let variant: 'outline' | 'ghost' = 'ghost';
                if (isCurrent) {
                  variant = 'outline';
                }
                return (
                  <Button
                    key={page}
                    type='button'
                    variant={variant}
                    size='icon'
                    aria-label={`Page ${page}`}
                    aria-current={currentPageOf(isCurrent)}
                    onClick={() => act({ type: 'paged', page })}
                    className={cn(
                      'tabular-nums',
                      pressedQuietOf(pressed === `page-${page}`)
                    )}
                  >
                    {page}
                  </Button>
                );
              })}
              <Button
                type='button'
                variant='ghost'
                size='icon'
                aria-label='Next page'
                disabled={state.page === pageCount}
                focusableWhenDisabled
                onClick={() => act({ type: 'paged', page: state.page + 1 })}
              >
                <ChevronRightIcon />
              </Button>
            </nav>
          )}

          {isNothingFound && (
            <div className='bg-foreground/[0.025] flex flex-col items-center gap-4 rounded-2xl px-6 py-10 text-center transition-opacity duration-200 starting:opacity-0'>
              <span className='keycap-3d flex size-10 items-center justify-center rounded-xl'>
                <SearchIcon className='text-muted-foreground size-5' />
              </span>
              <div className='flex flex-col gap-1'>
                <p className='text-sm font-medium text-balance'>
                  Nothing matches “{state.query.trim()}”
                </p>
                {correction && (
                  <p className='text-muted-foreground text-[13px]'>
                    Did you mean{' '}
                    <button
                      type='button'
                      onClick={(event) =>
                        pickSearch(correction, event.currentTarget)
                      }
                      className={cn(
                        'text-primary-ink rounded-sm font-medium underline-offset-4 transition-[scale] duration-150 hover:underline',
                        pressedQuietOf(pressed === 'correction'),
                        FOCUS_RING
                      )}
                    >
                      {correction}
                    </button>
                    ?
                  </p>
                )}
              </div>
              <PopularSearches onPick={pickSearch} className='justify-center' />
            </div>
          )}

          {isHiddenByType && (
            <div className='bg-foreground/[0.025] flex flex-col items-center gap-3 rounded-2xl px-6 py-10 text-center transition-opacity duration-200 starting:opacity-0'>
              <p className='text-sm font-medium text-balance'>
                {hiddenLineOf(state.type, state.query)}
              </p>
              <Button
                type='button'
                variant='outline'
                onClick={(event) => showEveryType(event.currentTarget)}
              >
                Show all {matches.length} {resultsWordOf(matches.length)}
              </Button>
            </div>
          )}

          {!hasWords && (
            <div className='flex flex-col gap-3 pt-2'>
              <p className='text-[13px] font-medium'>Popular searches</p>
              <PopularSearches onPick={pickSearch} />
            </div>
          )}
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  INSTANT,
  SPRING,
} from '@/registry/ndeko/lib/motion-presets';

import { TYPE_GLYPH, type IndexedPage } from './data';
import { markedPartsOf } from './search';

const ROW_SHOWN = { opacity: 1 };

const ROW_HIDDEN = { opacity: 0 };

const ROW_LEAVE: Transition = { duration: 0.1, ease: EASE_OUT_STRONG };

function rowMotionOf(shouldReduceMotion: boolean): Transition {
  if (shouldReduceMotion) {
    return { duration: 0.15, layout: INSTANT };
  }
  return { duration: 0.2, ease: EASE_OUT_STRONG, layout: SPRING };
}

function travelOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return SPRING;
}

export function optionIdOf(listId: string, index: number) {
  return `${listId}-${index}`;
}

function Marked({ text, words }: { text: string; words: string[] }) {
  const parts = markedPartsOf(text, words);

  return (
    <>
      {parts.map((part) => {
        if (part.isMatch) {
          return (
            <mark
              key={part.key}
              className='bg-primary/15 text-foreground rounded-[3px]'
            >
              {part.text}
            </mark>
          );
        }
        return <span key={part.key}>{part.text}</span>;
      })}
    </>
  );
}

function Trail({ trail }: { trail: string[] }) {
  return (
    <span className='text-muted-foreground flex min-w-0 items-center gap-1 text-xs'>
      {trail.map((step, index) => (
        <span key={step} className='flex min-w-0 items-center gap-1'>
          {index > 0 && <ChevronRightIcon className='size-3 shrink-0' />}
          <span className='truncate'>{step}</span>
        </span>
      ))}
    </span>
  );
}

type ResultListProps = {
  listId: string;
  results: IndexedPage[];
  words: string[];
  activeIndex: number;
};

/** The input keeps the focus; the arrows walk a highlight through these rows. */
export function ResultList({
  listId,
  results,
  words,
  activeIndex,
}: ResultListProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const layoutKey = results.map((page) => page.id).join(' ');

  return (
    <ul
      id={listId}
      role='listbox'
      aria-label='Results'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] relative flex flex-col rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <AnimatePresence mode='popLayout' initial={false}>
        {results.map((page, index) => {
          const Glyph = TYPE_GLYPH[page.type];
          const isActive = index === activeIndex;
          return (
            <motion.li
              key={page.id}
              role='none'
              layout
              layoutDependency={layoutKey}
              initial={ROW_HIDDEN}
              animate={ROW_SHOWN}
              exit={{ opacity: 0, transition: ROW_LEAVE }}
              transition={rowMotionOf(shouldReduceMotion)}
            >
              <a
                id={optionIdOf(listId, index)}
                role='option'
                aria-selected={isActive}
                href={page.href}
                tabIndex={-1}
                className='hover:bg-foreground/[0.03] relative isolate flex items-start gap-3 rounded-lg p-3 transition-colors duration-100 outline-none'
              >
                {isActive && (
                  <motion.span
                    layoutId={`${listId}-highlight`}
                    transition={travelOf(shouldReduceMotion)}
                    className='bg-foreground/[0.06] absolute inset-0 -z-10 rounded-lg'
                  />
                )}
                <span className='keycap-3d flex size-8 shrink-0 items-center justify-center rounded-lg'>
                  <Glyph className='text-muted-foreground size-4' />
                </span>
                <span className='flex min-w-0 flex-1 flex-col gap-1'>
                  <Trail trail={page.trail} />
                  <span className='text-[13px] font-medium text-pretty'>
                    <Marked text={page.title} words={words} />
                  </span>
                  <span className='text-muted-foreground line-clamp-2 text-xs leading-5 text-pretty'>
                    <Marked text={page.excerpt} words={words} />
                  </span>
                </span>
              </a>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ul>
  );
}

import { PAGES, type IndexedPage, type PageType } from './data';

export type TypeFilter = PageType | 'all';

export type MarkedPart = {
  key: string;
  text: string;
  isMatch: boolean;
};

type Range = {
  start: number;
  end: number;
};

type Scored = {
  page: IndexedPage;
  order: number;
  score: number;
};

/** A single letter matches nearly every page, so a word counts from two letters. */
const MIN_WORD_LENGTH = 2;

/** Corrections stay close to what was typed: at most two letters off. */
const MAX_DISTANCE = 2;

export function wordsOf(query: string) {
  const lowered = query.toLowerCase();
  const pieces = lowered.split(/\s+/);
  return pieces.filter((piece) => piece.length >= MIN_WORD_LENGTH);
}

function rangesOfWord(lowered: string, word: string) {
  const ranges: Range[] = [];
  let start = lowered.indexOf(word);
  while (start !== -1) {
    const end = start + word.length;
    ranges.push({ start, end });
    start = lowered.indexOf(word, end);
  }
  return ranges;
}

function byStart(first: Range, second: Range) {
  return first.start - second.start;
}

function mergedRanges(ranges: Range[]) {
  const sorted = [...ranges].sort(byStart);
  const merged: Range[] = [];
  for (const range of sorted) {
    const last = merged.at(-1);
    const overlaps = last !== undefined && range.start <= last.end;
    if (overlaps) {
      last.end = Math.max(last.end, range.end);
      continue;
    }
    merged.push({ ...range });
  }
  return merged;
}

export function markedPartsOf(text: string, words: string[]) {
  const lowered = text.toLowerCase();
  const ranges = words.flatMap((word) => rangesOfWord(lowered, word));
  const parts: MarkedPart[] = [];
  let cursor = 0;
  for (const range of mergedRanges(ranges)) {
    if (range.start > cursor) {
      const plain = text.slice(cursor, range.start);
      parts.push({ key: String(cursor), text: plain, isMatch: false });
    }
    const match = text.slice(range.start, range.end);
    parts.push({ key: String(range.start), text: match, isMatch: true });
    cursor = range.end;
  }
  if (cursor < text.length) {
    const rest = text.slice(cursor);
    parts.push({ key: String(cursor), text: rest, isMatch: false });
  }
  return parts;
}

/** Every word must be on the page; the words in its title count twice. */
function scoreOf(page: IndexedPage, words: string[]) {
  const title = page.title.toLowerCase();
  const text = `${title} ${page.excerpt.toLowerCase()}`;
  const isMatch = words.every((word) => text.includes(word));
  if (!isMatch) {
    return 0;
  }
  const inTitle = words.filter((word) => title.includes(word));
  return 1 + inTitle.length;
}

function byScoreThenOrder(first: Scored, second: Scored) {
  const scoreGap = second.score - first.score;
  if (scoreGap !== 0) {
    return scoreGap;
  }
  return first.order - second.order;
}

export function matchesOf(query: string) {
  const words = wordsOf(query);
  if (words.length === 0) {
    return [];
  }
  const scored = PAGES.map((page, order) => ({
    page,
    order,
    score: scoreOf(page, words),
  }));
  const matching = scored.filter((entry) => entry.score > 0);
  matching.sort(byScoreThenOrder);
  return matching.map((entry) => entry.page);
}

export function ofType(matches: IndexedPage[], type: TypeFilter) {
  if (type === 'all') {
    return matches;
  }
  return matches.filter((page) => page.type === type);
}

export function countOfType(matches: IndexedPage[], type: TypeFilter) {
  return ofType(matches, type).length;
}

function vocabularyOf(pages: IndexedPage[]) {
  const words = new Set<string>();
  for (const page of pages) {
    const text = `${page.title} ${page.excerpt}`.toLowerCase();
    for (const word of text.split(/[^a-z]+/)) {
      if (word.length >= 4) {
        words.add(word);
      }
    }
  }
  return [...words];
}

const VOCABULARY = vocabularyOf(PAGES);

/** How many letters to add, remove or change to turn one word into the other. */
function distanceBetween(first: string, second: string) {
  let previous = Array.from({ length: second.length + 1 }, (_, index) => index);
  for (let row = 1; row <= first.length; row += 1) {
    const current = [row];
    for (let column = 1; column <= second.length; column += 1) {
      const isSame = first[row - 1] === second[column - 1];
      let cost = 1;
      if (isSame) {
        cost = 0;
      }
      const removal = previous[column] + 1;
      const insertion = current[column - 1] + 1;
      const change = previous[column - 1] + cost;
      current.push(Math.min(removal, insertion, change));
    }
    previous = current;
  }
  return previous[second.length];
}

function closestWordOf(word: string) {
  let best = word;
  let bestDistance = MAX_DISTANCE + 1;
  for (const candidate of VOCABULARY) {
    const distance = distanceBetween(word, candidate);
    if (distance < bestDistance) {
      best = candidate;
      bestDistance = distance;
    }
  }
  return best;
}

export function correctionOf(query: string) {
  const words = wordsOf(query);
  if (words.length === 0) {
    return null;
  }
  const corrected = words.map(closestWordOf);
  const correction = corrected.join(' ');
  const original = words.join(' ');
  if (correction === original) {
    return null;
  }
  return correction;
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { matchesOf, ofType, type TypeFilter } from './search';

export type SearchState = {
  query: string;
  type: TypeFilter;
  /** The page of results, counted from 1. */
  page: number;
  /** The result Enter opens, on the current page. Nothing is highlighted before the arrows are used. */
  activeIndex: number;
  searchMs: number;
};

export type SearchAction =
  | { type: 'typed'; value: string }
  | { type: 'typePicked'; filter: TypeFilter }
  | { type: 'moved'; by: 1 | -1 }
  | { type: 'paged'; page: number }
  | { type: 'cleared' };

type Step = SessionStep<SearchState, SearchAction>;

export const PAGE_SIZE = 5;

const NOTHING_HIGHLIGHTED = -1;

export const INITIAL: SearchState = {
  query: '',
  type: 'all',
  page: 1,
  activeIndex: NOTHING_HIGHLIGHTED,
  searchMs: 0,
};

export function resultsIn(state: SearchState) {
  const matches = matchesOf(state.query);
  return ofType(matches, state.type);
}

export function pageCountOf(resultCount: number) {
  const pages = Math.ceil(resultCount / PAGE_SIZE);
  return Math.max(1, pages);
}

export function pageOfResults(state: SearchState) {
  const results = resultsIn(state);
  const start = (state.page - 1) * PAGE_SIZE;
  const end = start + PAGE_SIZE;
  return results.slice(start, end);
}

/** The search itself is timed where it runs, so the figure on the page is the real one. */
function searched(state: SearchState, query: string): SearchState {
  const startedAt = performance.now();
  matchesOf(query);
  const searchMs = performance.now() - startedAt;
  return {
    ...state,
    query,
    page: 1,
    activeIndex: NOTHING_HIGHLIGHTED,
    searchMs,
  };
}

function nextIndexOf(current: number, by: 1 | -1, count: number) {
  if (current === NOTHING_HIGHLIGHTED) {
    if (by === 1) {
      return 0;
    }
    return count - 1;
  }
  const moved = current + by + count;
  return moved % count;
}

function moved(state: SearchState, by: 1 | -1): SearchState {
  const count = pageOfResults(state).length;
  if (count === 0) {
    return state;
  }
  const activeIndex = nextIndexOf(state.activeIndex, by, count);
  return { ...state, activeIndex };
}

function paged(state: SearchState, page: number): SearchState {
  const resultCount = resultsIn(state).length;
  const pageCount = pageCountOf(resultCount);
  const isInRange = page >= 1 && page <= pageCount;
  if (!isInRange) {
    return state;
  }
  return { ...state, page, activeIndex: NOTHING_HIGHLIGHTED };
}

export function reducer(state: SearchState, action: SearchAction): SearchState {
  switch (action.type) {
    case 'typed':
      return searched(state, action.value);
    case 'typePicked':
      return {
        ...state,
        type: action.filter,
        page: 1,
        activeIndex: NOTHING_HIGHLIGHTED,
      };
    case 'moved':
      return moved(state, action.by);
    case 'paged':
      return paged(state, action.page);
    case 'cleared':
      return INITIAL;
  }
}

const KEY_MS = 95;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function arrow(after: number): Step {
  return {
    after,
    by: 'demo',
    press: 'key-down',
    action: { type: 'moved', by: 1 },
  };
}

function picked(after: number, filter: TypeFilter): Step {
  return {
    after,
    by: 'demo',
    press: `type-${filter}`,
    action: { type: 'typePicked', filter },
  };
}

